def extract_start_year(year_str):
    # Handle non-string inputs (e.g., if year_str is already numeric)
    if not isinstance(year_str, str):
        # If it's already a number, return it as int
        try:
            return int(year_str)
        except:
            return -9999
    parts = year_str.split(' - ')
    start_part = parts[0]
    try:
        return int(start_part)
    except ValueError:
        return -9999

